insert into quotes (id, account_id, exhibit_label, name, customer, status, quote_date, stage, synthesis_contact, synthesis_email_phone, customer_contact, customer_email_phone, implementation_items, rate_sel, po_rows) values ('quote_mtaz59at5kxn8', 'acc_radiologya2', 'A-1', 'RASLO - VetMed HL7 Integration', 'Radiology Associates of San Luis Obispo (RASLO)', 'Draft', '2026-08-26', 'Discovery', 'Shiv Kaura', 'skaura@synthesis.health', 'Marci Miller', 'skaura@synthesis.health', '["Additional HL7 Interface with VetMed "]'::jsonb, '{"hl7_dicom_interface": {"checked": true, "qty": 1}}'::jsonb, '[{"qty": "1", "item": "Additional HL7 or DICOM Interface (incl. gateway)", "price": "$500", "dueDate": "Monthly", "source": "rate:hl7_dicom_interface"}]'::jsonb);
insert into sows (id, account_id, customer, address, project_title, sow_date, status, stage, work_summary, work_details, solutions_diagram, meeting_notes) values ('sow_mtaz8qz7g73ik', 'acc_radiologya2', 'RASLO', '', 'RASLO - VetMed HL7 Integration', '2026-08-26', 'Draft', 'Discovery', 'Synthesis Health will establish a new HL7 interface between RASLO and VetMed to enable structured, automated exchange of data. This engagement covers interface configuration, connectivity testing, and validation to ensure reliable, ongoing data flow between the two systems. Synthesis Health will also provide the maintenance and support needed to keep the interface operating as expected post-go-live.', '["Configure the HL7 interface between RASLO and VetMed.", "Build and validate HL7 message mapping (e.g., ORM/ORU or applicable message types) to ensure correct field-level data exchange.", "Conduct end-to-end interface testing to verify message delivery and data accuracy.", "Monitor the interface post-go-live to confirm stable message flow and resolve any delivery errors.", "Provide ongoing maintenance of the HL7 interface to support ongoing reliability and uptime."]'::jsonb, true, 'Establish and maintain a new HL7 interface with VetMed. ');
